argv:
cat > app/package.json <<'EOF'
{
  "name": "fxcli",
  "version": "1.0.0",
  "private": true,
  "license": "Apache-2.0",
  "type": "module",
  "scripts": {
    "test": "node scripts/vendor-install.mjs && node --test"
  },
  "dependencies": {
    "@helmwright/fx-duration": "file:vendor/fx-duration"
  }
}
EOF

cat > app/src/timeout.js <<'EOF'
import { parseDuration } from "@helmwright/fx-duration";

/** Parses a --timeout value: whole milliseconds, or a duration such as 90s, 5m or 1h30m. */
export function parseTimeout(text) {
  return /^-?\d+$/.test(text) ? Number(text) : parseDuration(text);
}
EOF

cat > app/test/duration.test.js <<'EOF'
import assert from "node:assert/strict";
import { test } from "node:test";
import { parseTimeout } from "../src/timeout.js";

test("parses durations", () => {
  assert.equal(parseTimeout("90s"), 90_000);
  assert.equal(parseTimeout("5m"), 300_000);
  assert.equal(parseTimeout("1h30m"), 5_400_000);
});

test("rejects a malformed duration", () => {
  assert.throws(() => parseTimeout("5x"), RangeError);
  assert.throws(() => parseTimeout("30m1h"), RangeError);
});
EOF
